function localDate(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function afterDays(d){let x=new Date();x.setHours(12,0,0,0);x.setDate(x.getDate()+d);return localDate(x)}
function dayOf(iso){if(typeof iso!=='string')return '';let x=new Date(iso);return isNaN(x)?'':localDate(x)}
function recentOf(id){for(let i=state.history.length-1;i>=0;i--)if(state.history[i].id===id)return state.history[i];return null}
function allOf(id){return state.history.filter(h=>h.id===id)}
function isDue(q){return state.schedule[q.id]&&state.schedule[q.id].next<=localDate()}
function everWrong(q){return state.history.some(h=>h.id===q.id&&!h.correct)}
