function onChoose(){if(submitted)return;let inputs=[...$('choices').querySelectorAll('input')];let picks=inputs.filter(x=>x.checked);if(current.key.length===2&&picks.length>2)picks.at(-1).checked=false;selection=inputs.filter(x=>x.checked).map(x=>Number(x.value));[...$('choices').children].forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked))}
