function renderCategories(){let root=$('categoryGrid');root.innerHTML='';for(let c of DOMAINS){let qq=QUESTIONS.filter(x=>!x.provisional&&!x.void&&x.cat===c);let seen=qq.filter(x=>recentOf(x.id));let history=state.history.filter(x=>BYID[x.id]?.cat===c);let attempted=history.length,correct=history.filter(x=>x.correct).length;let div=document.createElement('div');div.className='group'+(!qq.length?' missing':'');let title=document.createElement('strong');title.textContent=c;div.append(title);let sm=document.createElement('small');sm.textContent=qq.length?('収録 '+qq.length+'問｜着手 '+seen.length+'問｜累計正答率 '+(attempted?Math.round(100*correct/attempted)+'%':'—')+'｜定着確認 '+qq.filter(mastered).length+'問'):'現在の演習問題には未収録';div.append(sm);let bar=document.createElement('div');bar.className='bar';let fill=document.createElement('div');fill.className='fill';fill.style.width=qq.length?(100*seen.length/qq.length)+'%':'0%';bar.append(fill);div.append(bar);if(qq.length){let b=document.createElement('button');b.className='tiny';b.textContent='この分野を演習';b.onclick=()=>{ $('studyCat').value=c;$('studyMode').value='all';begin('all',c)};div.append(b)}root.append(div)}}
